# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/registrar_sent_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.Worker.RegistrarSentTest do
  use ExUnit.Case, async: true

  import ExUnit.CaptureLog

  alias JoobQ.Error
  alias JoobQ.Worker.Registrar

  defp refused(status, code),
    do:
      {:error,
       Error.from_response(status, %{"error" => %{"code" => code, "message" => "no\nway"}})}

  test "a blueprint the gateway took is registered; a 5xx or no answer is sent again" do
    assert Registrar.sent("shop", {:ok, %{"created" => true}}) == :registered
    assert Registrar.sent("shop", refused(503, "unavailable")) == :retry

    assert Registrar.sent(
             "shop",
             {:error, %Error{reason: :transport, code: "transport_error", message: "closed"}}
           ) == :retry
  end

  test "a 4xx (429 included), an unencodable or a too large blueprint is refused for good, logged on one line" do
    not_text = %{"not" => "text"}
    unencodable = {:error, Error.unencodable()}
    too_large = {:error, :too_large}

    for {result, says} <- [
          {refused(422, "invalid"), "(422 invalid): no way"},
          {refused(429, "rate\nlimited"), "(429 rate limited)"},
          {refused(400, not_text), "(400 http_400)"},
          {unencodable, "cannot be encoded"},
          {too_large, "over 262144 bytes"}
        ] do
      log = capture_log(fn -> assert Registrar.sent("shop", result) == :refused end)
      assert log =~ "blueprint of workflow shop" and log =~ says
      assert log |> String.trim() |> String.split("\n") |> length() == 1
    end
  end
end
